<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import Chart from './Chart.vue';
import Icon from './Icon.vue';
import { AnalyticsError, converted, formatValue as n, fraction, publishedRequest } from '../analytics';
import { behaviorBucketLabel, behaviorHeatmap, correlationHeatmap, demandHeatmap, dimensionLabel, efficiencyBubble, failurePareto, heatMetrics, segmentSunburst, serviceFlow, serviceSuccessHeatmap, weatherHeatmap, weekdays } from '../advancedAnalytics';
import type { AdvancedData, AdvancedFilters, BehaviorMetric, HeatMetric, ServiceCell, StationPoint } from '../advancedAnalytics';

const props = withDefaults(defineProps<{ filters: AdvancedFilters; topic: 'space' | 'service'; stations: { stationId: string; stationName: string }[]; presentation?: boolean }>(), { presentation: false });
const data = ref<AdvancedData>();
const error = ref(''); const loading = ref(false);
const siteType = ref(''); const stationId = ref(''); const stationTypes = ref<string[]>([]);
const metric = ref<HeatMetric>('chargingUtilization');
const behaviorMetric = ref<BehaviorMetric>('intervals');
const selectedServiceKey = ref('');
const selectedService = computed(() => data.value?.service.cells.find(row => serviceKey(row) === selectedServiceKey.value));
const selectedFailures = computed(() => [...selectedService.value?.failures || []].filter(row => row.count > 0).sort((a, b) => b.count - a.count || a.reason.localeCompare(b.reason)));
const otherFailures = computed(() => ({ reasons: Math.max(0, selectedFailures.value.length - 4), count: selectedFailures.value.slice(4).reduce((sum, row) => sum + row.count, 0) }));
const serviceTypes = computed(() => [...new Set(data.value?.service.cells.map(row => row.siteType) || [])].sort());
const selectedStation = ref<StationPoint>();
const table = ref('heatmap'); const page = ref(0);
let alive = true; let sequence = 0; let controller: AbortController | undefined;
const heatOption = computed(() => demandHeatmap(data.value?.heatmap || [], metric.value));
const bubbleOption = computed(() => efficiencyBubble(data.value?.stations || []));
const weatherOption = computed(() => weatherHeatmap(data.value?.weather || []));
const behaviorOption = computed(() => data.value ? behaviorHeatmap(data.value.behavior, behaviorMetric.value) : {});
const successOption = computed(() => serviceSuccessHeatmap(data.value?.service.cells || [], selectedService.value));
const failureOption = computed(() => failurePareto(data.value?.service.failures || []));
const flowOption = computed(() => serviceFlow(data.value?.flow || { attemptCount: 0, nodes: [], links: [] }));
const segmentOption = computed(() => segmentSunburst(data.value?.segments || []));
const correlationOption = computed(() => correlationHeatmap(data.value?.correlations || []));
const coverage = computed(() => data.value && data.value.summary.observedStationHours > 0 ? data.value.summary.completeStationHours / data.value.summary.observedStationHours : null);
const excludedStations = computed(() => data.value?.stations.filter(row => converted(row.chargingUtilization) === null || converted(row.meanWaitMinutes) === null || converted(row.energyKwh) === null).length || 0);
const visibleInsights = computed(() => props.topic === 'service' ? data.value?.insights.slice(-3) || [] : data.value?.insights.slice(0, 3) || []);
const tables = computed(() => props.topic === 'space'
  ? [{ id: 'heatmap', label: '星期与小时' }, { id: 'stations', label: '电站效能' }, { id: 'weather', label: '气温与时段' }, { id: 'correlations', label: '指标相关性' }]
  : [{ id: 'intervals', label: '平台复充间隔分布' }, { id: 'energy', label: '单次补电分布' }, { id: 'behavior', label: '用户补能摘要' }, { id: 'failures', label: '未成功原因' }, { id: 'access', label: '各入口成功率' }, { id: 'service', label: '站型与小时瓶颈' }, { id: 'flow', label: '服务转化' }, { id: 'segments', label: '会话结构' }]);
const detail = computed<{ columns: string[]; rows: string[][] }>(() => {
  const source = data.value;
  if (!source) return { columns: [], rows: [] };
  switch (table.value) {
    case 'stations': return { columns: ['城市', '电站', '站型', '利用率', '平均等待/分钟', '电量/kWh', '会话数', '成功率', '净收款/元'], rows: source.stations.map(row => [row.cityName, row.stationName, dimensionLabel(row.siteType), fraction(row.chargingUtilization), n(row.meanWaitMinutes, 1), n(row.energyKwh, 1), n(row.sessionCount), fraction(row.successRate), n(row.netCashYuan, 2)]) };
    case 'weather': return { columns: ['气温区间/°C（右端不含）', '小时', '利用率', '平均功率/kW', '有效站点小时'], rows: source.weather.map(row => [`${row.temperatureBin} — ${row.temperatureBin + 5}`, String(row.hour).padStart(2, '0'), fraction(row.chargingUtilization), n(row.meanPowerKw, 2), n(row.sampleHours)]) };
    case 'intervals': case 'energy': return { columns: ['用户群体', '区间（左含右不含）', '次数', '群体内占比'], rows: source.behavior[table.value].map(row => [dimensionLabel(row.userSegment), behaviorBucketLabel(row.bucket, table.value as BehaviorMetric), n(row.count), fraction(row.share)]) };
    case 'behavior': return { columns: ['用户群体', '会话数', '有效间隔数', '首次观测数', '平均间隔/天', '平均单次电量/kWh'], rows: source.behavior.segments.map(row => [dimensionLabel(row.userSegment), n(row.sessionCount), n(row.intervalCount), n(row.firstObservedCount), n(row.meanIntervalDays, 2), n(row.meanEnergyKwh, 2)]) };
    case 'failures': return { columns: ['未成功原因', '次数', '占未成功尝试', '占全部尝试'], rows: source.service.failures.map(row => [row.label, n(row.count), fraction(row.shareOfFailures), fraction(row.shareOfAttempts)]) };
    case 'access': return { columns: ['进入方式', '尝试数', '成功开始数', '成功率'], rows: source.service.accessPaths.map(row => [row.label, n(row.attemptCount), n(row.successfulAttempts), fraction(row.successRate)]) };
    case 'service': return { columns: ['站型', '小时', '尝试数', '成功开始', '成功率', '平均等待/分钟', '已解决排队数', '充后占位占比', '会话数', '充电利用率', '完整站点小时', '接口/静态桩数/额定kW'], rows: source.service.cells.map(row => [dimensionLabel(row.siteType), `${String(row.hour).padStart(2, '0')}:00`, n(row.attemptCount), n(row.successfulAttempts), fraction(row.successRate), n(row.meanWaitMinutes, 1), n(row.queueWaitCount), fraction(row.overstayShare), n(row.sessionCount), fraction(row.chargingUtilization), n(row.completeStationHours), row.interfaces.map(item => `${item.connectorType} / ${item.chargerCount} / ${n(item.ratedPowerKw, 1)}`).join('；')]) };
    case 'flow': return { columns: ['起点', '去向', '尝试次数'], rows: source.flow.links.map(row => [row.source, row.target, n(row.value)]) };
    case 'segments': return { columns: ['站型', '用户群体', '电池容量/kWh', '接口', '会话数', '电量/kWh', '平均充电/分钟', '平均充后占位/分钟'], rows: source.segments.map(row => [dimensionLabel(row.siteType), dimensionLabel(row.userSegment), dimensionLabel(row.batteryCapacityBand), dimensionLabel(row.connectorType), n(row.sessionCount), n(row.energyKwh, 1), n(row.meanChargeMinutes, 1), n(row.meanOverstayMinutes, 1)]) };
    case 'correlations': return { columns: ['指标 X', '指标 Y', 'Pearson r', '成对完整样本数'], rows: source.correlations.map(row => [dimensionLabel(row.x), dimensionLabel(row.y), n(row.value, 3), n(row.n)]) };
    default: return { columns: ['星期', '小时', '电量/kWh', '平均功率/kW', '利用率', '有效站点小时'], rows: source.heatmap.map(row => [weekdays[row.weekday] || '—', String(row.hour).padStart(2, '0'), n(row.energyKwh, 1), n(row.meanPowerKw, 2), fraction(row.chargingUtilization), n(row.sampleHours)]) };
  }
});
const pageCount = computed(() => Math.max(1, Math.ceil(detail.value.rows.length / 40)));
const tableRows = computed(() => detail.value.rows.slice(page.value * 40, (page.value + 1) * 40));

async function refresh() {
  const current = ++sequence; controller?.abort(); controller = new AbortController();
  const signal = controller.signal;
  loading.value = true; error.value = ''; data.value = undefined; selectedStation.value = undefined; selectedServiceKey.value = ''; page.value = 0;
  const filters = { ...props.filters, siteType: siteType.value, stationId: stationId.value || props.filters.stationId };
  try {
    const response = await publishedRequest<AdvancedData>('/dashboard/advanced', filters, { signal });
    if (!alive || current !== sequence) return;
    const result = response.data;
    if (!result?.summary || !result.provenance || !result.flow || !result.behavior || !result.service || !Array.isArray(result.heatmap) || !Array.isArray(result.stations) || !Array.isArray(result.weather) || !Array.isArray(result.segments) || !Array.isArray(result.correlations) || !Array.isArray(result.stationTypes) || !Array.isArray(result.provenance.notes) || !Array.isArray(result.insights) || !Array.isArray(result.behavior.intervals) || !Array.isArray(result.behavior.energy) || !Array.isArray(result.behavior.segments) || !Array.isArray(result.service.cells) || !Array.isArray(result.service.failures) || !Array.isArray(result.service.accessPaths) || !Array.isArray(result.flow.nodes) || !Array.isArray(result.flow.links)) throw new Error('多维分析响应不完整，请检查发布产物。');
    data.value = result;
    // Begin with the most frequent observed group, not the lowest rate in a tiny sample.
    const initialCell = [...result.service.cells].filter(row => row.attemptCount > 0).sort((a, b) => b.attemptCount - a.attemptCount || a.siteType.localeCompare(b.siteType) || a.hour - b.hour)[0];
    selectedServiceKey.value = initialCell ? serviceKey(initialCell) : '';
    stationTypes.value = [...new Set([...stationTypes.value, ...result.stationTypes])].sort();
  } catch (failure) {
    if (!alive || current !== sequence) return;
    if (!(failure instanceof AnalyticsError && failure.code === 'CANCELLED')) error.value = failure instanceof Error ? failure.message : '多维分析加载失败。';
  } finally { if (alive && current === sequence) loading.value = false; }
}
function selectStation(event: { data?: unknown }) {
  const row = (event.data as { row?: StationPoint } | undefined)?.row;
  if (row?.stationId && data.value?.stations.some(station => station.stationId === row.stationId)) selectedStation.value = row;
}
function chooseStation(event: Event) {
  const id = (event.target as HTMLSelectElement).value;
  selectedStation.value = data.value?.stations.find(row => row.stationId === id);
}
function serviceKey(row: Pick<ServiceCell, 'siteType' | 'hour'>) { return `${row.siteType}:${row.hour}`; }
function selectService(event: { data?: unknown }) {
  const row = (event.data as { row?: ServiceCell } | undefined)?.row;
  if (row && data.value?.service.cells.some(cell => serviceKey(cell) === serviceKey(row))) selectedServiceKey.value = serviceKey(row);
}
function resetDimensions() { siteType.value = ''; stationId.value = ''; }
watch(() => props.filters, () => { resetDimensions(); stationTypes.value = []; }, { deep: true, flush: 'sync' });
watch([() => props.filters, siteType, stationId], refresh, { deep: true, immediate: true });
watch(() => props.topic, () => { table.value = props.topic === 'space' ? 'heatmap' : 'intervals'; page.value = 0; }, { immediate: true });
watch(table, () => { page.value = 0; });
onBeforeUnmount(() => { alive = false; sequence++; controller?.abort(); });
</script>

<template>
  <section class="advanced-analytics" :class="{ 'advanced-presentation': presentation }" aria-label="多维运营分析">
    <header class="advanced-heading">
      <div><div class="eyebrow">{{ topic === 'space' ? 'SPACE · TIME · CAPACITY' : 'PEOPLE · JOURNEY · STRUCTURE' }}</div><h2>{{ topic === 'space' ? '把需求，放回时空之中。' : '从需求差异，找到服务瓶颈。' }}</h2><p>{{ topic === 'space' ? '城市、站型、时段与环境交叉分析，寻找需求集中和资源失衡。' : '先看用户如何补能，再追踪未成功原因，最后定位具体站型与时段。' }}</p></div>
      <span class="advanced-scope-tag"><Icon name="sliders" :size="15"/>联动当前城市与日期</span>
    </header>
    <div class="advanced-dimensions">
      <label>站点类型<select v-model="siteType" aria-label="分析站点类型" @change="stationId = ''"><option value="">全部站型</option><option v-for="type in stationTypes" :key="type" :value="type">{{ dimensionLabel(type) }}</option></select></label>
      <label class="advanced-station-filter">电站范围<select v-model="stationId" aria-label="分析电站范围"><option value="">当前城市全部电站</option><option v-for="station in stations" :key="station.stationId" :value="station.stationId">{{ station.stationName }}</option></select></label>
      <button v-if="siteType || stationId" class="text-button" @click="resetDimensions">重置下钻</button>
      <span>上方“应用筛选”控制城市与日期；这里可继续按站型、电站下钻。</span>
    </div>
    <div v-if="presentation" class="advanced-presentation-scope"><span>{{ topic === 'space' ? '时空与效率' : '用户与服务' }}</span><span>{{ siteType ? dimensionLabel(siteType) : '全部站型' }} · {{ stationId ? stations.find(station => station.stationId === stationId)?.stationName || stationId : '当前范围全部电站' }}</span><small>退出大屏可调整筛选</small></div>
    <div v-if="loading" class="advanced-loading" role="status"><span class="spinner dark"></span><div><strong>正在计算这个范围的交叉视角</strong><p>读取已发布多维统计，不使用静态示例替代。</p></div></div>
    <div v-else-if="error" class="analytics-error" role="alert"><Icon name="info" :size="20"/><div><strong>多维分析暂不可用</strong><p>{{ error }}</p><small>基础运营总览不受影响；请确认当前批次已发布多维分析产物。</small></div><button class="button secondary" @click="refresh">重试分析</button></div>
    <template v-else-if="data">
      <div class="advanced-source"><span class="advanced-source-dot"></span><strong>{{ data.provenance.sourceLabel }}</strong><span>{{ data.provenance.engine }}</span><span class="advanced-source-id" :title="data.provenance.analysisId">{{ data.provenance.analysisId }}</span></div>
      <div class="advanced-evidence-strip" aria-label="分析样本范围">
        <div><small>参与电站</small><b>{{ n(data.summary.stationCount) }}<em>座</em></b></div><div><small>充电会话</small><b>{{ n(data.summary.sessionCount) }}<em>次</em></b></div><div><small>服务尝试</small><b>{{ n(data.summary.attemptCount) }}<em>次</em></b></div><div><small>完整站点小时 / 已观测</small><b>{{ fraction(coverage) }}</b><span>{{ n(data.summary.completeStationHours) }} / {{ n(data.summary.observedStationHours) }}</span></div>
      </div>
      <div v-if="visibleInsights.length && !presentation" class="advanced-findings" aria-label="当前范围的统计发现"><article v-for="(insight, index) in visibleInsights" :key="insight"><span>0{{ index + 1 }} / 统计发现</span><p>{{ insight }}</p></article></div>

      <div v-if="topic === 'space'" class="advanced-chart-grid">
        <article class="card advanced-chart-card">
          <div class="advanced-card-heading"><div><span class="advanced-kicker">01 / 需求节律</span><h3>一周中的充电高峰</h3><p>星期 × 小时 × 站型 × 城市</p></div><label class="advanced-metric"><span class="sr-only">需求热力图指标</span><select v-model="metric" aria-label="需求热力图指标"><option v-for="item in heatMetrics" :key="item.id" :value="item.id">{{ item.label }}</option></select></label></div>
          <Chart v-if="data.heatmap.some(row => converted(row[metric]) !== null)" :option="heatOption" :label="`按星期与小时分析${heatMetrics.find(item => item.id === metric)?.label}，城市与站型以当前筛选为准`"/>
          <div v-else class="advanced-empty">当前范围没有有效小时样本。</div>
          <p class="advanced-chart-note">横轴为北京时间；颜色表示指标强度。悬浮查看有效站点小时数；留白为缺测，不表示零。</p>
        </article>
        <article class="card advanced-chart-card">
          <div class="advanced-card-heading"><div><span class="advanced-kicker">02 / 资源效率</span><h3>繁忙，是否也意味着等待？</h3><p>利用率 × 等待 × 电量 × 站型 × 城市</p></div><span class="tiny-tag">点击气泡下钻</span></div>
          <Chart v-if="data.stations.length > excludedStations" :option="bubbleOption" label="电站资源效率气泡图，横轴利用率、纵轴平均等待、大小电量、颜色站型。可用下方选择框查看同样的数据。" @select="selectStation"/>
          <div v-else class="advanced-empty">当前范围缺少可同时比较的利用率与排队样本。</div>
          <p class="advanced-chart-note">气泡越大，充电量越多；等待使用已解决排队事件的均值。{{ excludedStations ? `${excludedStations} 个电站因缺测未绘制，原始值仍可查。` : '相关位置用于比较，不预设“优秀”阈值。' }}</p>
          <div class="advanced-station-detail"><label>查看电站<select :value="selectedStation?.stationId || ''" aria-label="查看电站效能明细" @change="chooseStation"><option value="">选择气泡或电站</option><option v-for="station in data.stations" :key="station.stationId" :value="station.stationId">{{ station.stationName }}</option></select></label><template v-if="selectedStation"><dl><div><dt>成功率</dt><dd>{{ fraction(selectedStation.successRate) }}</dd></div><div><dt>充后占位占比</dt><dd>{{ fraction(selectedStation.overstayShare) }}</dd></div><div><dt>净收款</dt><dd>¥{{ n(selectedStation.netCashYuan, 2) }}</dd></div></dl><button class="text-button" @click="stationId = selectedStation.stationId">仅分析该站 <Icon name="arrow" :size="14"/></button></template></div>
        </article>
        <article class="card advanced-chart-card">
          <div class="advanced-card-heading"><div><span class="advanced-kicker">03 / 环境关联</span><h3>不同气温下的小时需求</h3><p>温度区间 × 小时 × 利用率</p></div><span class="tiny-tag">5°C 分箱</span></div>
          <Chart v-if="data.weather.some(row => row.chargingUtilization !== null)" :option="weatherOption" label="不同气温和小时的充电利用率热力图，悬浮可读样本量；这是相关性而非因果推断。"/>
          <div v-else class="advanced-empty">当前范围没有可关联的天气与完整小时样本。</div>
          <p class="advanced-chart-note">按站点小时关联天气。温度、城市、季节与用户构成相互关联；这里只描述共同变化，不判断因果。</p>
        </article>
        <article class="card advanced-chart-card">
          <div class="advanced-card-heading"><div><span class="advanced-kicker">04 / 关联结构</span><h3>哪些指标一起变化？</h3><p>成对完整样本的 Pearson 相关系数</p></div><span class="tiny-tag">−1 到 +1</span></div>
          <Chart v-if="data.correlations.some(row => row.value !== null)" :option="correlationOption" label="运营指标成对相关矩阵，蓝色为正相关、棕色为负相关；样本量与具体值见数据明细。"/>
          <div v-else class="advanced-empty">样本不足或指标无变异，无法估计相关系数。</div>
          <p class="advanced-chart-note">接近 ±1 表示线性关联较强。缺测与无变异保留为空；请结合样本量及分组比较，相关不等于因果。</p>
        </article>
      </div>

      <div v-else class="advanced-chart-grid advanced-service-grid">
        <article class="card advanced-chart-card advanced-behavior">
          <div class="advanced-card-heading"><div><span class="advanced-kicker">01 / 补能行为</span><h3>谁回站频繁，谁一次充得多？</h3><p>用户类型 × 平台补能分布 · 群体内占比</p></div><label class="advanced-metric"><span class="sr-only">补能分布指标</span><select v-model="behaviorMetric" aria-label="补能分布指标"><option value="intervals">平台复充间隔</option><option value="energy">单次补电</option></select></label></div>
          <Chart v-if="data.behavior[behaviorMetric].some(row => row.share !== null)" :option="behaviorOption" label="不同用户群体的平台复充间隔或单次电量分布热力图，百分比分母是该群体有效间隔数或会话数，不是人数。"/>
          <div v-else class="advanced-empty">当前范围没有可比较的{{ behaviorMetric === 'intervals' ? '相邻充电间隔' : '单次电量' }}样本。</div>
          <div class="advanced-behavior-samples"><span><b>{{ n(behaviorMetric === 'intervals' ? data.behavior.intervalCount : data.behavior.sessionCount) }}</b> {{ behaviorMetric === 'intervals' ? '个有效间隔' : '次充电会话' }}</span><span v-if="behaviorMetric === 'intervals'">排除 <b>{{ n(data.behavior.firstObservedCount) }}</b> 次首次观测</span></div>
          <p class="advanced-chart-note">{{ behaviorMetric === 'intervals' ? '本平台相邻两次充电开始之间的时间，跨站回看历史；仅当前这次充电受页面日期与站点筛选。首次观测不等于新注册用户，也不当作零天间隔。仅统计本平台记录，车辆可能在站外补能，不代表全部充电间隔。' : '同一群体内按单次充电量分箱，区间左含右不含。每行比例合计 100%，用于比较分布，不用总量代替行为差异。' }} 当前为固定用户池，不据此推断获客或流失。</p>
        </article>
        <article class="card advanced-chart-card">
          <div class="advanced-card-heading"><div><span class="advanced-kicker">02 / 服务转化</span><h3>需求具体因为什么流失？</h3><p>充电尝试 → 进入方式 → 成功或具体原因</p></div><span class="tiny-tag">{{ n(data.flow.attemptCount) }} 次尝试</span></div>
          <Chart v-if="data.flow.links.some(link => link.value > 0)" :option="flowOption" label="服务尝试流程桑基图，流宽代表同一批次尝试数，不同阶段不可相加当作用户总数。"/>
          <div v-else class="advanced-empty">当前范围没有服务尝试的有效流向。</div>
          <div class="advanced-access-paths" aria-label="各进入方式的尝试成功率"><div v-for="path in data.service.accessPaths" :key="path.path"><span>{{ path.label }}</span><b>{{ fraction(path.successRate) }}</b><small>{{ n(path.successfulAttempts) }} / {{ n(path.attemptCount) }} 次成功开始</small></div></div>
          <p class="advanced-chart-note">线宽是次数，不是人数；节点间追踪同一批尝试。比较入口看成功率及分母，而不是只看线宽；成功开始不等于已完成或已支付。</p>
        </article>
        <article class="card advanced-chart-card advanced-failures">
          <div class="advanced-card-heading"><div><span class="advanced-kicker">03 / 原因优先级</span><h3>先处理哪一类未满足需求？</h3><p>具体原因 × 次数 × 累计覆盖比例</p></div><span class="tiny-tag">{{ n(data.service.failedAttempts) }} 次未成功</span></div>
          <Chart v-if="data.service.failures.some(row => row.count > 0)" :option="failureOption" label="未成功原因帕累托图，柱高为次数，折线为累计占未成功尝试的比例，不代表修复后的确定收益。"/>
          <div v-else class="advanced-empty">当前范围没有未成功尝试。</div>
          <p class="advanced-chart-note">累计线回答“前几类原因覆盖了多少未成功尝试”。这是排查优先级，不意味着解决某个原因就能挽回全部需求；完整名称与两个分母见数据明细。</p>
        </article>
        <article class="card advanced-chart-card advanced-bottlenecks">
          <div class="advanced-card-heading"><div><span class="advanced-kicker">04 / 场景定位</span><h3>哪类站，在几点更难充上？</h3><p>站型 × 北京时间 × 尝试成功率</p></div><span class="tiny-tag">点击色块查看关联</span></div>
          <Chart v-if="data.service.cells.some(row => row.successRate !== null)" :option="successOption" label="站型和小时尝试成功率热力图，点击色块联动下方资源背景；也可通过下方选择框选择同一个场景。" @select="selectService"/>
          <div v-else class="advanced-empty">当前范围没有尝试样本，留白不代表成功率为零。</div>
          <p class="advanced-chart-note">颜色越蓝成功率越高，浅棕色表示较低成功率。悬浮看分子与分母；先结合样本量，再比较场景，缺测不填零。</p>
        </article>
        <article class="card advanced-chart-card advanced-service-context" aria-label="选中场景的资源关联">
          <div class="advanced-card-heading"><div><span class="advanced-kicker">场景联动 / RESOURCE CONTEXT</span><h3>把低成功率，放回资源背景。</h3><p>点击上方热力图，或选择站型与时段，交叉检查排队、占位与接口结构。</p></div><label class="advanced-context-select">当前场景<select v-model="selectedServiceKey" aria-label="选择服务瓶颈场景"><option value="">选择一个场景</option><optgroup v-for="type in serviceTypes" :key="type" :label="dimensionLabel(type)"><option v-for="cell in data.service.cells.filter(row => row.siteType === type)" :key="serviceKey(cell)" :value="serviceKey(cell)">{{ dimensionLabel(type) }} · {{ String(cell.hour).padStart(2, '0') }}:00 · {{ n(cell.attemptCount) }} 次尝试</option></optgroup></select></label></div>
          <template v-if="selectedService">
            <div class="advanced-context-title"><strong>{{ dimensionLabel(selectedService.siteType) }} · {{ String(selectedService.hour).padStart(2, '0') }}:00–{{ String(selectedService.hour + 1).padStart(2, '0') }}:00</strong><span>{{ n(selectedService.stationCount) }} 座电站</span><span v-if="selectedService.attemptCount < 30" class="advanced-small-sample">小样本 · 少于 30 次，不宜单独下结论</span></div>
            <dl class="advanced-context-metrics"><div><dt>尝试成功率</dt><dd>{{ fraction(selectedService.successRate) }}</dd><small>{{ n(selectedService.successfulAttempts) }} / {{ n(selectedService.attemptCount) }} 次尝试</small></div><div><dt>平均排队等待</dt><dd>{{ n(selectedService.meanWaitMinutes, 1) }}<em>分钟</em></dd><small>{{ n(selectedService.queueWaitCount) }} 条已解决排队</small></div><div><dt>充后占位占比</dt><dd>{{ fraction(selectedService.overstayShare) }}</dd><small>{{ n(selectedService.sessionCount) }} 次开始于本时段的会话</small></div><div><dt>充电利用率</dt><dd>{{ fraction(selectedService.chargingUtilization) }}</dd><small>{{ n(selectedService.completeStationHours) }} 个完整站点小时</small></div></dl>
            <div class="advanced-context-bottom"><div><h4>{{ otherFailures.reasons ? '该场景的主要未成功原因（前 4 项）' : '该场景的未成功原因' }}</h4><ol v-if="selectedFailures.length" class="advanced-reason-list"><li v-for="reason in selectedFailures.slice(0, 4)" :key="reason.reason"><span>{{ reason.label }}</span><strong>{{ n(reason.count) }} 次</strong><small>{{ fraction(reason.shareOfFailures) }} / 未成功尝试</small></li></ol><p v-else class="advanced-chart-note">本场景没有未成功尝试；不将其解读为未来零风险。</p><p v-if="otherFailures.reasons" class="advanced-chart-note" aria-label="其余未成功原因">另有 {{ n(otherFailures.reasons) }} 类原因，共 {{ n(otherFailures.count) }} 次未成功尝试，已计入本场景成功率的分母。</p></div><div><h4>当前站点接口结构</h4><div class="advanced-interface-inventory"><div v-for="item in selectedService.interfaces" :key="item.connectorType"><span>{{ dimensionLabel(item.connectorType) }}</span><b>{{ n(item.chargerCount) }}<em>桩</em></b><small>额定功率合计 {{ n(item.ratedPowerKw, 1) }} kW</small></div><p v-if="!selectedService.interfaces.length" class="advanced-chart-note">暂无接口清单。</p></div><p class="advanced-chart-note">站点静态装机清单，不随日期或小时重复累计；额定功率不等于实际输出。</p></div></div>
            <p class="advanced-chart-note advanced-context-definition">{{ data.service.definition }} 这些指标描述同一站型与时段下的关联，来自不同事件集合；不能据此确定因果或直接决定扩容。</p>
          </template><div v-else class="advanced-empty">选择一个场景查看对应样本、占位、排队与接口信息。</div>
        </article>
        <article class="card advanced-chart-card advanced-segments">
          <div class="advanced-card-heading"><div><span class="advanced-kicker">05 / 多层结构</span><h3>谁，在哪，怎样充电？</h3><p>站型 → 用户群体 → 电池容量 → 充电接口</p></div><span class="tiny-tag">点击逐层查看</span></div>
          <div class="advanced-segment-layout"><Chart v-if="data.segments.some(row => row.sessionCount > 0)" :option="segmentOption" label="四层会话结构旭日图，由内向外为站型、用户群体、电池容量档位、接口，面积代表会话次数。完整分类组合可在数据明细中查看。"/><div v-else class="advanced-empty">当前范围没有可分组的会话。</div><div class="advanced-segment-guide"><h4>从总量，拆解到具体人群。</h4><ol><li><b>01</b><div><strong>站点类型</strong><p>商业、社区、园区等场景。</p></div></li><li><b>02</b><div><strong>用户群体</strong><p>不同出行目的对应不同需求。</p></div></li><li><b>03</b><div><strong>电池容量</strong><p>按 kWh 档位比较容量结构。</p></div></li><li><b>04</b><div><strong>充电接口</strong><p>按接口进一步细分会话。</p></div></li></ol><p class="advanced-chart-note">面积代表会话次数；同一会话只属于一条分类路径。点击扇区逐层查看，点击中心返回上层；表格可比较电量、时长和充后占位。</p></div></div>
        </article>
      </div>

      <div v-if="visibleInsights.length && presentation" class="advanced-findings advanced-findings--after-charts" aria-label="当前范围的统计发现"><article v-for="(insight, index) in visibleInsights" :key="insight"><span>0{{ index + 1 }} / 统计发现</span><p>{{ insight }}</p></article></div>
      <details class="card advanced-data-details">
        <summary><div><h3>数据明细与分析口径</h3><p>每个图形都能追溯到分组值、分母和样本量。</p></div><span>展开查看 ＋</span></summary>
        <div class="advanced-table-toolbar"><label>查看图表数据<select v-model="table" aria-label="选择多维分析明细"><option v-for="item in tables" :key="item.id" :value="item.id">{{ item.label }}</option></select></label><span>共 {{ n(detail.rows.length) }} 行 · “—”为缺测，不是零</span></div>
        <div class="advanced-table-scroll" tabindex="0" aria-label="可横向滚动的数据明细表"><table><caption>{{ tables.find(item => item.id === table)?.label }} · 当前已应用范围</caption><thead><tr><th v-for="column in detail.columns" :key="column" scope="col">{{ column }}</th></tr></thead><tbody><tr v-for="(row, index) in tableRows" :key="index"><td v-for="(cell, cellIndex) in row" :key="cellIndex">{{ cell }}</td></tr><tr v-if="!tableRows.length"><td :colspan="detail.columns.length">当前范围没有记录。</td></tr></tbody></table></div>
        <div class="advanced-pagination"><button class="button secondary" :disabled="page === 0" @click="page--">上一页</button><span aria-live="polite">{{ page + 1 }} / {{ pageCount }}</span><button class="button secondary" :disabled="page >= pageCount - 1" @click="page++">下一页</button></div>
        <div class="advanced-method"><h4>来源与边界</h4><p>{{ data.provenance.sourceLabel }} · {{ data.provenance.engine }} · {{ data.provenance.analysisId }}</p><ul><li v-for="note in data.provenance.notes" :key="note">{{ note }}</li></ul><p>{{ data.behavior.definition }}</p><p>分析产物生成时间：{{ data.provenance.generatedAt }}。图表遵循本页已应用范围；补能间隔的上一笔充电跨站回看全历史，不按本页开始日期截断，当前充电才受筛选约束。</p></div>
      </details>
    </template>
  </section>
</template>

